insert into whatsapp_tools_w2 values
('whatsapp-message-stats','إحصاءات رسالة واتساب','WhatsApp Message Stats','احسب الكلمات والأحرف والأسطر في رسالة واتساب.','Count words, characters, and lines in a WhatsApp message.','[{"type":"stats"}]'::jsonb,'one','الرسالة','Message','احسب الإحصاءات','Calculate stats',10000,null,null,null,null,null,7401),
('whatsapp-status-decorator','زخرفة حالة واتساب','WhatsApp Status Decorator','زخرف نص حالة واتساب بأنماط بسيطة قابلة للنسخ.','Decorate WhatsApp status text with simple copy-ready styles.','[{"type":"trim"},{"type":"decorate","style_key":"style"}]'::jsonb,'style','نص الحالة','Status text','زخرف الحالة','Decorate status',10000,null,null,null,null,null,7402),
