('whatsapp-arabic-normalizer','تطبيع العربية لواتساب','WhatsApp Arabic Normalizer','وحّد أشكال الحروف العربية ونظف المسافات في الرسالة.','Normalize Arabic letter forms and spacing in a message.','[{"type":"normalize_arabic"}]'::jsonb,'one','الرسالة العربية','Arabic message','طبّع الرسالة','Normalize message',10000,null,null,null,null,null,7404),
('whatsapp-phone-link-generator','مولد رابط واتساب من رقم','WhatsApp Phone Link Generator','حوّل رقم الهاتف إلى رابط wa.me مباشر بعد حذف الرموز والمسافات.','Turn a phone number into a direct wa.me link after removing symbols and spaces.','[{"type":"remove_punctuation"},{"type":"remove_whitespace"},{"type":"prefix","value":"https://wa.me/"}]'::jsonb,'one','رقم الهاتف مع رمز الدولة','Phone number with country code','أنشئ الرابط','Generate link',100,null,null,null,null,null,7405),
('whatsapp-broadcast-sorter','ترتيب قائمة بث واتساب','WhatsApp Broadcast Sorter','رتب قائمة أسماء أو أرقام البث أبجديًا.','Sort a WhatsApp broadcast list alphabetically.','[{"type":"sort_lines","direction":"asc"}]'::jsonb,'one','قائمة البث','Broadcast list','رتب القائمة','Sort list',10000,null,null,null,null,null,7406),
('whatsapp-broadcast-counter','عداد قائمة بث واتساب','WhatsApp Broadcast Counter','احسب عدد الأسطر والعناصر النصية في قائمة البث.','Count lines and text items in a broadcast list.','[{"type":"stats"}]'::jsonb,'one','قائمة البث','Broadcast list','احسب','Count',10000,null,null,null,null,null,7407),
('whatsapp-italic-text','تنسيق مائل لواتساب','WhatsApp Italic Formatter','ضع الشرطة السفلية حول النص لتنسيقه كمائل في واتساب.','Wrap text with underscores for WhatsApp italic formatting.','[{"type":"prefix","value":"_"},{"type":"suffix","value":"_"}]'::jsonb,'one','النص','Text','نسق كمائل','Format italic',10000,null,null,null,null,null,7408),
('whatsapp-strikethrough-text','تنسيق مشطوب لواتساب','WhatsApp Strikethrough Formatter','ضع علامة ~ حول النص لتنسيقه كمشطوب في واتساب.','Wrap text with ~ for WhatsApp strikethrough formatting.','[{"type":"prefix","value":"~"},{"type":"suffix","value":"~"}]'::jsonb,'one','النص','Text','نسق كمشطوب','Format strikethrough',10000,null,null,null,null,null,7409),
('whatsapp-code-text','تنسيق كود لواتساب','WhatsApp Code Formatter','ضع ثلاث علامات اقتباس خلفية حول النص لعرضه ككتلة كود.','Wrap text in triple backticks for WhatsApp code formatting.','[{"type":"prefix","value":"```"},{"type":"suffix","value":"```"}]'::jsonb,'one','النص أو الكود','Text or code','نسق ككود','Format as code',10000,null,null,null,null,null,7410);
insert into public.tools(slug,title_ar,title_en,short_description,category_id,engine_type,input_schema,output_schema,runtime_config,provider_strategy,model_alias,prompt_template,pricing_mode,fixed_points,minimum_points,cost_multiplier,requires_auth,is_featured,is_active,sort_order,seo_title,seo_description)
insert into public.tool_translations(tool_id,locale_id,title,short_description,seo_title,seo_description,prompt_template_override) select t.id,l.id,case when l.code='ar' then s.title_ar else s.title_en end,case when l.code='ar' then s.description_ar else s.description_en end,case when l.code='ar' then s.title_ar else s.title_en end,case when l.code='ar' then s.description_ar else s.description_en end,null from whatsapp_tools_w2_ready s join public.tools t on t.slug=s.slug join public.locales l on l.code in('ar','en') on conflict(tool_id,locale_id) do update set title=excluded.title,short_description=excluded.short_description,seo_title=excluded.seo_title,seo_description=excluded.seo_description,prompt_template_override=null,updated_at=now();
insert into public.tool_field_translations(tool_id,locale_id,field_key,label,placeholder,help_text,options) select t.id,l.id,f->>'key',f->>'label',nullif(f->>'placeholder',''),nullif(f->>'helpText',''),f->'options' from whatsapp_tools_w2_ready s join public.tools t on t.slug=s.slug join public.locales l on l.code in('ar','en') cross join lateral jsonb_array_elements(case when l.code='ar' then s.schema_ar->'fields' else s.schema_en->'fields' end) f on conflict(tool_id,locale_id,field_key) do update set label=excluded.label,placeholder=excluded.placeholder,help_text=excluded.help_text,options=excluded.options,updated_at=now();
insert into public.tool_field_translations(tool_id,locale_id,field_key,label,placeholder,help_text,options) select t.id,l.id,'__submit__',case when l.code='ar' then s.submit_ar else s.submit_en end,null,null,null from whatsapp_tools_w2_ready s join public.tools t on t.slug=s.slug join public.locales l on l.code in('ar','en') on conflict(tool_id,locale_id,field_key) do update set label=excluded.label,updated_at=now();
